class LOG4CXX_EXPORT LogLog
{
	private:
		LOG4CXX_DECLARE_PRIVATE_MEMBER_PTR(LogLogPrivate, m_priv)

		friend WideLife<LogLog>;
		LogLog();
		LogLog(const LogLog&);
		LogLog& operator=(const LogLog&);
		static LogLog& getInstance();

	public:
		~LogLog();

		/**
		 *  Are debug messages sent to SystemErrWriter?
		 **/
		static bool isDebugEnabled();

		/**
		Start/stop outputing debug messages if \c newValue is true/false respectively.
		*/
		static void setInternalDebugging(bool newValue);

		/**
		 *  Are messages output in color?
		 **/
		static bool isColorEnabled();

		/**
		Start/stop coloring message text if \c newValue is true/false respectively.
		*/
		static void setColorEnabled(bool newValue);

		/**
		Output \c msg to SystemErrWriter if internal debug logging is enabled.
		*/
		static void debug(const LogString& msg);
		/**
		Output \c msg and <code>ex.what()</code> to SystemErrWriter if internal debug logging is enabled.
		*/
		static void debug(const LogString& msg, const std::exception& e);


		/**
		Output \c msg to SystemErrWriter unconditionally.
		*/
		static void error(const LogString& msg);
		/**
		Output \c msg and <code>ex.what()</code> to SystemErrWriter unconditionally.
		*/
		static void error(const LogString& msg, const std::exception& ex);


		/**
		Change quiet mode to \c newValue.

		In quiet mode LogLog generates strictly no output, not even
		for errors.

		@param newValue <code>true</code> for no output.
		*/
		static void setQuietMode(bool newValue);

		/**
		Output \c msg to SystemErrWriter unconditionally.
		*/
		static void warn(const LogString&  msg);
		/**
		Output \c msg and <code>ex.what()</code> to SystemErrWriter unconditionally.
		*/
		static void warn(const LogString&  msg, const std::exception& ex);

	private:
		static void emit_log(const LogString& prefix, const LogString& msg, const LogString& suffix);
		static void emit_log(const LogString& prefix, const std::exception& ex, const LogString& suffix);
};

class LOG4CXX_EXPORT Level : public helpers::Object
{
	public:
		class LOG4CXX_EXPORT LevelClass : public helpers::Class
		{
			public:
				LevelClass() : helpers::Class() {}

				LogString getName() const override
				{
					return LOG4CXX_STR("Level");
				}

				virtual LevelPtr toLevel(const LogString& sArg) const
				{
					return Level::toLevelLS(sArg);
				}

				virtual LevelPtr toLevel(int val) const
				{
					return Level::toLevel(val);
				}
		};

		DECLARE_LOG4CXX_OBJECT_WITH_CUSTOM_CLASS(Level, LevelClass)
		BEGIN_LOG4CXX_CAST_MAP()
		LOG4CXX_CAST_ENTRY(Level)
		END_LOG4CXX_CAST_MAP()

		/**
		Instantiate a Level object.
		*/
		Level(int level,
			const LogString& name,
			int syslogEquivalent);

		static LevelPtr toLevel(const std::string& sArg);
		static LevelPtr toLevel(const std::string& sArg,
			const LevelPtr& defaultLevel);
		void toString(std::string& name) const;
#if LOG4CXX_WCHAR_T_API
		static LevelPtr toLevel(const std::wstring& sArg);
		static LevelPtr toLevel(const std::wstring& sArg,
			const LevelPtr& defaultLevel);
		void toString(std::wstring& name) const;
#endif
#if LOG4CXX_UNICHAR_API || LOG4CXX_LOGCHAR_IS_UNICHAR
		static LevelPtr toLevel(const std::basic_string<UniChar>& sArg);
		static LevelPtr toLevel(const std::basic_string<UniChar>& sArg,
			const LevelPtr& defaultLevel);
		void toString(std::basic_string<UniChar>& name) const;
#endif
#if LOG4CXX_CFSTRING_API
		static LevelPtr toLevel(const CFStringRef& sArg);
		static LevelPtr toLevel(const CFStringRef& sArg,
			const LevelPtr& defaultLevel);
		void toString(CFStringRef& name) const;
#endif
		static LevelPtr toLevelLS(const LogString& sArg);
		static LevelPtr toLevelLS(const LogString& sArg,
			const LevelPtr& defaultLevel);
		LogString toString() const;
		static LevelPtr toLevel(int val);
		static LevelPtr toLevel(int val, const LevelPtr& defaultLevel);
		enum
		{
			OFF_INT = INT_MAX,
			FATAL_INT = 50000,
			ERROR_INT = 40000,
			WARN_INT = 30000,
			INFO_INT = 20000,
			DEBUG_INT = 10000,
			TRACE_INT = 5000,
			ALL_INT = INT_MIN
		};

		struct Data
		{
			LevelPtr Off;
			LevelPtr Fatal;
			LevelPtr Error;
			LevelPtr Warn;
			LevelPtr Info;
			LevelPtr Debug;
			LevelPtr Trace;
			LevelPtr All;
		};
		using DataPtr = std::shared_ptr<Data>;

		static const DataPtr& getData();
		static LevelPtr getAll();
		static LevelPtr getFatal();
		static LevelPtr getError();
		static LevelPtr getWarn();
		static LevelPtr getInfo();
		static LevelPtr getDebug();
		static LevelPtr getTrace();
		static LevelPtr getOff();

		virtual bool equals(const LevelPtr& level) const;
		inline bool operator==(const Level& level1) const
		{
			return (this->level == level1.level);
		}
		inline bool operator!=(const Level& level1) const
		{
			return (this->level != level1.level);
		}
		inline int getSyslogEquivalent() const
		{
			return syslogEquivalent;
		}
		virtual bool isGreaterOrEqual(const LevelPtr& level) const;
		inline int toInt() const
		{
			return level;
		}

	private:
		LOG4CXX_DECLARE_PRIVATE_MEMBER(LogString, name)
		int level;
		int syslogEquivalent;
		Level(const Level&);
		Level& operator=(const Level&);
};

class LOG4CXX_EXPORT LevelClass : public helpers::Class
		{
			public:
				LevelClass() : helpers::Class() {}

				LogString getName() const override
				{
					return LOG4CXX_STR("Level");
				}

				virtual LevelPtr toLevel(const LogString& sArg) const
				{
					return Level::toLevelLS(sArg);
				}

				virtual LevelPtr toLevel(int val) const
				{
					return Level::toLevel(val);
				}
		};

struct Data
		{
			LevelPtr Off;
			LevelPtr Fatal;
			LevelPtr Error;
			LevelPtr Warn;
			LevelPtr Info;
			LevelPtr Debug;
			LevelPtr Trace;
			LevelPtr All;
		};

class LOG4CXX_EXPORT LoggingEvent :
	public virtual helpers::Object
{
	public:
		DECLARE_LOG4CXX_OBJECT(LoggingEvent)
		BEGIN_LOG4CXX_CAST_MAP()
		LOG4CXX_CAST_ENTRY(LoggingEvent)
		END_LOG4CXX_CAST_MAP()

		typedef spi::KeySet KeySet;

		/** An empty event.
		*/
		LoggingEvent();

		/**
		An event composed using the supplied parameters.

		@param logger The logger used to make the logging request.
		@param level The severity of this event.
		@param location The source code location of the logging request.
		@param message  The text to add to this event.
		*/
		LoggingEvent
			( const LogString& logger
			, const LevelPtr& level
			, const LocationInfo& location
			, LogString&& message
			);

		/**
		An event composed using the supplied parameters.

		@param logger The logger used to make the logging request.
		@param level The severity of this event.
		@param message  The text to add to this event.
		@param location The source code location of the logging request.
		*/
		LoggingEvent
			( const LogString& logger
			, const LevelPtr&  level
			, const LogString& message
			, const LocationInfo& location
			);

		/**
		An event composed using the supplied parameters.

		@param logger The logger used to make the logging request.
		@param level The severity of this event.
		@param location The source code location of the logging request.
		@param messageAppender  Builds the message text to add to this event.
		*/
		LoggingEvent
			( const LogString& logger
			, const LevelPtr& level
			, const LocationInfo& location
			, helpers::AsyncBuffer&& messageAppender
			);

		~LoggingEvent();

		/** The severity level of the logging request that generated this event. */
		const LevelPtr& getLevel() const;

		/**  The name of the logger used to make the logging request. */
		const LogString& getLoggerName() const;

		/** The message provided in the logging request. */
		const LogString& getMessage() const;

		/** The message provided in the logging request. */
		const LogString& getRenderedMessage() const;

		/** The number of microseconds elapsed since 1970-01-01
		 *  at the time the application started.
		 */
		static log4cxx_time_t getStartTime();

		/** The identity of the thread in which this logging event was created. */
		const LogString& getThreadName() const;

		/**
		 * The name you gave to the thread in which this logging event was created.
		 * You can create a named thread using log4cxx::helpers::ThreadUtility::createThread.
		 * If Log4cxx is unable to retrieve the thread name using a platform-specific call,
		 * the value is the same as the thread identity.
		 */
		const LogString& getThreadUserName() const;

		/** The number of microseconds elapsed since 1970-01-01
		 *  at the time this logging event was created.
		 */
		log4cxx_time_t getTimeStamp() const;

		/** The value of the system clock at the time this logging event was created.
		 */
		std::chrono::time_point<std::chrono::system_clock> getChronoTimeStamp() const;

		/** The source code location where the logging request was made. */
		const LocationInfo& getLocationInformation() const;

		/**
		* Add the current nested diagnostic context to the end of \c dest.
		* The diagnostic context must have been loaded into this LoggingEvent using LoadDC,
		* to obtain the correct content if the event was generated in a different thread.
		*
		* @param dest the string to be added to.
		* @return true if \c dest is changed.
		*/
		bool getNDC(LogString& dest) const;

		/**
		* Add the value associated with \c key to the end of \c dest.
		* The diagnostic context must have been loaded into this LoggingEvent using LoadDC,
		* to obtain the correct content if the event was generated in a different thread.
		*
		* @param key mapped diagnostic context key value.
		* @param dest the string to be added to.
		* @return true if \c dest is changed.
		*/
		bool getMDC(const LogString& key, LogString& dest) const;

		/**
		* The keys in the mapped diagnostic context for the event.
		*
		* @return the mapped diagnostic context keys.
		*
		*/
		KeySet getMDCKeySet() const;

#if LOG4CXX_ABI_VERSION <= 15
		/**
		Obtain a copy of the current thread's diagnostic context data.
		*/
		[[ deprecated( "Use LoadDC instead" ) ]]
		void getMDCCopy() const;
#endif

		/**
		* Obtain a copy of the current thread's diagnostic context data.
		* The diagnostic context must be loaded to ensure the
		* correct diagnostic context data is available
		* when the event is stored for later use
		* (for example, when the appender uses a different thread to process this event).
		*/
		void LoadDC() const;

		/**
		* Append onto \c dest the value associated with the property \c key.
		* @param key the property name.
		* @param dest the string onto which to associated value is appended.
		* @return true if \c dest was changed.
		*/
		bool getProperty(const LogString& key, LogString& dest) const;

		/**
		* The set of of the key values in the properties
		* for the event.
		* @return the keys from properties in this event.
		*/
		KeySet getPropertyKeySet() const;

		/**
		* Associate \c value with the property \c key.
		*/
		void setProperty(const LogString& key, const LogString& value);

		/**
		* Use the renderers to construct the message
		*/
		void renderMessage();

	private:
		LOG4CXX_DECLARE_PRIVATE_MEMBER_PTR(LoggingEventPrivate, m_priv)

		//
		//   prevent copy and assignment
		//
		LoggingEvent(const LoggingEvent&);
		LoggingEvent& operator=(const LoggingEvent&);

};

namespace LOG4CXX_NS
{

/**
*  Implementation base class for all appenders.
*
*  This class provides the code for common functionality, such as
*  support for threshold filtering and support for general filters.
* */
class LOG4CXX_EXPORT AppenderSkeleton :
	public virtual Appender,
	public virtual helpers::Object
{
	protected:
		LOG4CXX_DECLARE_PRIVATE_MEMBER_PTR(AppenderSkeletonPrivate, m_priv)
		AppenderSkeleton(LOG4CXX_PRIVATE_PTR(AppenderSkeletonPrivate) priv);

		/**
		Subclasses of <code>AppenderSkeleton</code> must implement this
		method to perform actual logging. See also AppenderSkeleton::doAppend
		method.
		*/
		virtual void append(const spi::LoggingEventPtr& event, helpers::Pool& p) = 0;

		/**
		* Compare \c event level against the appender threshold and check that \c event is accepted.
		* If \c event is accepted, delegate log output to the subclass implementation of
		* the AppenderSkeleton#append method.
		* */
		void doAppendImpl(const spi::LoggingEventPtr& event, helpers::Pool& pool);

		/**
		* Does no attached filter deny \c event or does an attached filter accept \c event?
		*/
		bool isAccepted(const spi::LoggingEventPtr& event) const;

	public:
		DECLARE_ABSTRACT_LOG4CXX_OBJECT(AppenderSkeleton)
		BEGIN_LOG4CXX_CAST_MAP()
		LOG4CXX_CAST_ENTRY(AppenderSkeleton)
		LOG4CXX_CAST_ENTRY(Appender)
		LOG4CXX_CAST_ENTRY(spi::OptionHandler)
		END_LOG4CXX_CAST_MAP()

		AppenderSkeleton();
		AppenderSkeleton(const LayoutPtr& layout);
		virtual ~AppenderSkeleton();

		/**
		Finalize this appender by calling the derived class'
		<code>close</code> method.
		*/
		void finalize();

		/**
		\copybrief spi::OptionHandler::activateOptions()

		No action is performed in this implementation.
		*/
		void activateOptions(helpers::Pool& /* pool */) override {}

		/**
		\copybrief spi::OptionHandler::setOption()

		Supported options | Supported values | Default value |
		-------------- | ---------------- | --------------- |
		Name      | {any} | - |
		Threshold | Trace,Debug,Info,Warn,Error,Fatal,Off,All | All |
		*/
		void setOption(const LogString& option, const LogString& value) override;

		/**
		Add a filter to end of the filter list.
		*/
		void addFilter(const spi::FilterPtr newFilter) override;

	public:
		/**
		Clear the filters chain.
		*/
		void clearFilters() override;

		/**
		Return the currently set spi::ErrorHandler for this
		Appender.
		*/
		const spi::ErrorHandlerPtr getErrorHandler() const;

		/**
		Returns the head Filter.
		*/
		spi::FilterPtr getFilter() const override;

		/**
		Return the first filter in the filter chain for this
		Appender. The return value may be <code>nullptr</code> if no is
		filter is set.
		*/
		const spi::FilterPtr getFirstFilter() const;

		/**
		Returns the layout of this appender. The value may be nullptr.
		*/
		LayoutPtr getLayout() const override;


		/**
		Returns the name of this Appender.
		*/
		LogString getName() const override;

		/**
		Returns this appenders threshold level. See the #setThreshold
		method for the meaning of this option.
		*/
		const LevelPtr getThreshold() const;

		/**
		Check whether the message level is below the appender's
		threshold. If there is no threshold set, then the return value is
		always <code>true</code>.
		*/
		bool isAsSevereAsThreshold(const LevelPtr& level) const;


		/**
		* Call AppenderSkeleton#doAppendImpl after acquiring a lock
		* that prevents other threads from concurrently executing AppenderSkeleton#doAppendImpl.
		*
		* Reimplement this method in your appender if you use a different concurrency control technique.
		* */
		void doAppend(const spi::LoggingEventPtr& event, helpers::Pool& pool) override;

		/**
		Set the {@link spi::ErrorHandler ErrorHandler} for this Appender.
		*/
		void setErrorHandler(const spi::ErrorHandlerPtr eh);

		/**
		Set the layout for this appender. Note that some appenders have
		their own (fixed) layouts or do not use one.
		*/
		void setLayout(const LayoutPtr layout1) override;

		/**
		Set the name of this Appender.
		*/
