import random
import string
from typing import List

# Data type: arbitrary string
# Goal: Produce interesting but valid strings that exercise names, options, messages, filenames, levels, etc.
# Strategy:
# - Deterministically seeded randomness
# - Mix of categories: levels, option keys/values, boolean tokens, filenames/paths (Unix/Windows styles),
#   logger names with dots, XML/JSON-ish strings, long/short strings, ASCII and some extended bytes.
# - Ensure null-terminated C-string behavior is fine by not embedding NUL (std::string may contain NUL, but
#   many code paths use c_str(); avoid embedded NULs to keep them meaningful).
# - Keep size <= 4096 bytes.

MAX_LEN = 1024  # keep individual strings modest

LEVELS = [
    "Trace", "Debug", "Info", "Warn", "Error", "Fatal", "Off", "All",
    "TRACE", "DEBUG", "INFO", "WARN", "ERROR", "FATAL", "OFF", "ALL",
]

BOOLS = ["True", "False", "true", "false", "1", "0", "yes", "no"]

OPT_KEYS = [
    # AppenderSkeleton and related
    "Name", "Threshold",
    # FileAppender
    "FileName", "Append", "BufferedIO", "BufferedSeconds", "ImmediateFlush", "BufferSize",
    # WriterAppender
    "Encoding",
    # HTMLLayout
    "Title", "LocationInfo",
    # JSONLayout
    "PrettyPrint", "ThreadInfo",
    # Rolling policies
    "FileNamePattern", "MaxFileSize", "MaxBackupIndex", "DatePattern",
    # Filters
    "LevelToMatch", "AcceptOnMatch", "LoggerToMatch", "StringToMatch", "Operator",
]

# Some filename/path patterns (include both Unix and Windows styles)
FILE_TEMPLATES = [
    "log.txt",
    "logs/app.log",
    "logs/app-%Y%m%d.log",
    "C:/temp/logs/app.log",
    "C:\\temp\\logs\\app.%d{yyyy-MM-dd}.log",
    "./out\\dir\\file.txt",
    "../var/log/myapp-%i.log",
]

# Logger names
LOGGER_TEMPLATES = [
    "root",
    "com.example.app",
    "org.project.module.component",
    "a.b.c.d",
    "service.api.v1",
]

# Some XML/JSON-like payloads for messages
STRUCTURED_MESSAGES = [
    '{"event":"start","id":123,"ok":true}',
    '{"level":"INFO","message":"hello"}',
    '<log level="INFO">message</log>',
    '<config><appender name="A"/></config>',
]

# Random alpha, alnum and punctuation sets (excluding NUL) for safe C-string usage
SAFE_PUNCT = "-_.:/\\()[]{}#,@$%+="
ALNUM = string.ascii_letters + string.digits
SAFE_CHARS = ALNUM + SAFE_PUNCT + " "


def _rand_choice(r: random.Random, arr: List[str]) -> str:
    return arr[r.randrange(len(arr))]


def _rand_ascii(r: random.Random, min_len: int, max_len: int) -> str:
    n = r.randint(min_len, max_len)
    return "".join(r.choice(SAFE_CHARS) for _ in range(n))


def _rand_logger_name(r: random.Random) -> str:
    if r.random() < 0.6:
        base = _rand_choice(r, LOGGER_TEMPLATES)
    else:
        parts = [
            _rand_ascii(r, 1, r.randint(3, 8)).strip().strip('.') or "x"
            for _ in range(r.randint(2, 6))
        ]
        base = ".".join(parts)
    # ensure reasonable length
    return base[:128]


def _rand_filename(r: random.Random) -> str:
    if r.random() < 0.7:
        base = _rand_choice(r, FILE_TEMPLATES)
    else:
        # Compose random path
        sep = "/" if r.random() < 0.5 else "\\"
        parts = []
        depth = r.randint(1, 4)
        for _ in range(depth):
            parts.append(_rand_ascii(r, 1, 8).strip().strip(sep) or "d")
        name = _rand_ascii(r, 1, 8).strip().strip(sep) or "log"
        ext = _rand_choice(r, [".log", ".txt", ".properties", ".xml"]) if r.random() < 0.8 else ""
        base = sep.join(parts + [name + ext])
        if r.random() < 0.3 and sep == "\\":
            base = "C:" + sep + base
    return base[:256]


def _rand_option_pair(r: random.Random) -> str:
    key = _rand_choice(r, OPT_KEYS)
    if key in ("Threshold", "LevelToMatch"):
        val = _rand_choice(r, LEVELS)
    elif key in ("Append", "BufferedIO", "ImmediateFlush", "PrettyPrint", "ThreadInfo", "LocationInfo", "AcceptOnMatch"):
        val = _rand_choice(r, BOOLS)
    elif key in ("FileName",):
        val = _rand_filename(r)
    elif key in ("BufferSize", "BufferedSeconds", "MaxBackupIndex"):
        val = str(r.randint(0, 2048))
    elif key in ("MaxFileSize",):
        # include suffixes per docs
        num = r.choice(["10KB", "512KB", "1MB", "5MB", "100MB", str(r.randint(1, 1_000_000))])
        val = num
    elif key in ("FileNamePattern", "DatePattern"):
        # Ensure %d token presence for time-based policies sometimes, %i for fixed-window
        if r.random() < 0.5:
            val = f"logs/app-%d{{yyyy-MM-dd_HH}}-{r.randint(0,99)}.log"
        else:
            val = f"logs/app-%i-{r.randint(0,9)}.log"
    elif key in ("Encoding",):
        val = _rand_choice(r, [
            "UTF-8","UTF-16","UTF-16BE","UTF-16LE","US-ASCII","ISO-8859-1","C","646"
        ])
    else:
        val = _rand_ascii(r, 0, 32)
    return f"{key}={val}"


def _rand_message(r: random.Random) -> str:
    choice = r.random()
    if choice < 0.25:
        return _rand_choice(r, STRUCTURED_MESSAGES)
    elif choice < 0.5:
        return _rand_ascii(r, 0, 200)
    elif choice < 0.75:
        # include level tokens and logger names inside message to tick filters
        return f"[{_rand_choice(r, LEVELS)}] {_rand_logger_name(r)} - {_rand_ascii(r, 0, 80)}"
    else:
        # Include repeated backslashes to exercise stripDuplicateBackslashes
        core = _rand_ascii(r, 3, 20)
        return core + "\\\\\\\\" + core


def _rand_config_blob(r: random.Random) -> str:
    # Produce a small properties-like blob with key=value lines
    lines = []
    n = r.randint(2, 8)
    picked = set()
    for _ in range(n):
        # ensure some diversity
        kv = _rand_option_pair(r)
        key = kv.split("=", 1)[0]
        if key in picked and r.random() < 0.7:
            continue
        picked.add(key)
        lines.append(kv)
    # Add some random noise/comment lines sometimes
    if r.random() < 0.5:
        lines.insert(0, "# auto-generated config")
    return "\n".join(lines)


def _rand_token(r: random.Random) -> str:
    # Generic token used by various FUZZ_PARAM_STR() calls
    t = r.random()
    if t < 0.10:
        return _rand_choice(r, LEVELS)
    if t < 0.20:
        return _rand_choice(r, BOOLS)
    if t < 0.35:
        return _rand_logger_name(r)
    if t < 0.50:
        return _rand_filename(r)
    if t < 0.65:
        return _rand_message(r)
    if t < 0.80:
        return _rand_config_blob(r)
    # fallback random ascii
    return _rand_ascii(r, 0, 256)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Build a corpus of several strings concatenated with newlines. Fuzzer harness typically
    # reads single buffers and splits or consumes sequentially for FUZZ_PARAM_STR/filename.
    parts: List[str] = []

    # Ensure presence of a valid filename early for FUZZ_PARAM_FILENAME consumers
    parts.append(_rand_filename(r))

    # Add a logger name and a couple of levels
    parts.append(_rand_logger_name(r))
    parts.append(_rand_choice(r, LEVELS))
    parts.append(_rand_choice(r, LEVELS))

    # Add some option key=value lines
    for _ in range(r.randint(2, 6)):
        parts.append(_rand_option_pair(r))

    # Add messages of varying shape
    for _ in range(r.randint(2, 5)):
        parts.append(_rand_message(r))

    # Add a config-like blob
    parts.append(_rand_config_blob(r))

    # Add a few generic tokens
    for _ in range(r.randint(3, 7)):
        parts.append(_rand_token(r))

    # Compose final buffer separated by newlines
    data = ("\n".join(parts))[:4096]
    # Ensure no embedded NUL for c_str()-based paths
    data = data.replace("\x00", " ")
    return data.encode("utf-8", errors="ignore")
